package com.zhuqiyun.exchange;
import com.zhuqiyun.platform.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.util.*;import java.io.*;import java.math.*;import java.time.*;import static com.zhuqiyun.domain.Rules.*;
@Service
public class ExportService {
 private final Db db;private final Auth auth;private final RecordQueryService queries;
 public ExportService(Db db,Auth auth,RecordQueryService queries){this.db=db;this.auth=auth;this.queries=queries;}
 private LinkedHashMap<String,String> columns(String entity) {
  LinkedHashMap<String,String> c=new LinkedHashMap<>();
  String fields=switch(entity) {
   case "suppliers","materials","projects","warehouses" -> null;
   case "requests" -> "code:申请单号 project_name:项目 status:状态 total_amount:申请金额 required_date:需求日期 applicant_name:申请人 note:申请说明 created_at:申请时间";
   case "orders" -> "code:订单单号 project_name:项目 supplier_name:供应商 status:状态 total_amount:原订单额 closed_amount:关闭金额 effective_amount:净订单额 buyer_name:采购人 created_at:下单时间";
   case "contracts" -> "code:合同编号 name:合同名称 type:合同类型 project_name:项目 supplier_name:供应商 order_code:关联订单 amount:合同金额 status:状态 signed_date:签订日期 start_date:开始日期 end_date:结束日期 created_at:创建时间";
   case "cost-overview" -> "code:项目编号 name:项目名称 budget_amount:项目预算 material_cost:领料材料成本 other_cost:其他费用 actual_cost:实际总成本 budget_usage:预算使用率(%) registered_cost_balance:合同额减已登记成本";
   case "expenses" -> "project_name:项目 category:费用类型 description:费用说明 amount:发生金额 incurred_date:发生日期 operator_name:经办人 created_at:登记时间";
   case "receipts" -> "code:入库单号 order_code:订单 project_name:项目 warehouse_name:仓库 reference:凭证 amount:验收金额 operator_name:制单人 created_at:制单时间";
   case "issues" -> "code:领料单号 project_name:项目 warehouse_name:仓库 reference:凭证 amount:领料成本 operator_name:制单人 created_at:制单时间";
   case "issue-returns" -> "code:退料单号 issue_code:原领料单 project_name:项目 warehouse_name:仓库 reference:退料凭证 amount:退回成本 reason:退料原因 operator_name:经办人 created_at:退料时间";
   case "inventory" -> "material_name:材料 specification:规格 unit:单位 warehouse_name:仓库 quantity:现存数量 safety_stock:安全库存 average_price:加权均价 stock_value:库存金额";
   case "stock-movements" -> "reference:业务凭证 kind:业务类型 material_name:材料 warehouse_name:仓库 project_name:项目 quantity:数量 unit:单位 unit_cost:单位成本 amount:金额 operator_name:经办人 created_at:发生时间";
   case "stocktakes" -> "code:盘点单号 warehouse_name:仓库 status:状态 applicant_name:制单人 reviewer_name:审核人 note:备注 review_comment:审核意见 submitted_at:提交时间 reviewed_at:审核时间 created_at:创建时间";
   case "payables" -> "order_code:采购订单 project_name:项目 supplier_name:供应商 amount:退货后应付 paid_amount:净实付 outstanding_amount:未付余额 refunded_amount:累计退款 refundable_amount:待收退款 reserved_amount:申请占用 available_amount:可申请余额";
   case "payment-applications" -> "id:申请编号 order_code:采购订单 project_name:项目 supplier_name:供应商 amount:申请金额 applicant_name:申请人 status:状态 review_comment:审批意见 reviewed_at:审批时间 note:申请说明 created_at:申请时间";
   case "payments" -> "reference:付款凭证 order_code:采购订单 project_name:项目 supplier_name:供应商 amount:实付金额 operator_name:经办人 note:说明 created_at:付款时间";
   case "supplier-refunds" -> "reference:退款凭证 order_code:采购订单 project_name:项目 supplier_name:供应商 amount:实收退款 operator_name:经办人 note:说明 created_at:退款时间";
   case "supplier-statement" -> "order_code:订单 project_name:项目 supplier_name:供应商 receipt_amount:原验收额 return_amount:退货冲减 amount:净应付 original_paid_amount:原实付 refunded_amount:累计退款 paid_amount:净实付 reserved_amount:申请占用 available_amount:可申请 outstanding_amount:未付 refundable_amount:待收退款";
   default -> throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"不支持的导出类型");
  };
  if(fields==null){c.putAll(ImportService.columns(entity));c.remove("manager_username");if(entity.equals("projects"))c.put("manager_name","项目负责人");}
  else for(String field:fields.split(" ")){var pair=field.split(":",2);c.put(pair[0],pair[1]);}
  if(!auth.can("cost:read")){c.remove("budget_amount");if(Set.of("issues","issue-returns").contains(entity))c.remove("amount");}
  if(!auth.can("cost:read")&&!auth.can("stocktake:approve")&&Set.of("inventory","stock-movements").contains(entity))for(String key:List.of("average_price","stock_value","unit_cost","amount"))c.remove(key);
  if(!auth.can("contract:read")){c.remove("contract_amount");c.remove("registered_cost_balance");}
  return c;
 }
 private List<Map<String,Object>> rows(String entity,Map<String,String> filters){Map<String,String> f=new HashMap<>(filters);f.put("page","1");f.put("size","5000");var result=queries.page(entity,f,5000);Fields.check(((Number)result.get("total")).longValue()<=5000,"筛选结果超过5000条，请缩小范围后导出或打印");return (List<Map<String,Object>>)result.get("items");}
 private boolean numeric(String key){return key.endsWith("amount")||key.endsWith("_cost")||Set.of("stock_value","average_price","budget_usage","registered_cost_balance","quantity","unit_price","unit_cost","received_quantity","closed_quantity","remaining_quantity","returned_quantity","snapshot_quantity","counted_quantity","difference_quantity","rating","safety_stock","reference_price","progress").contains(key);}
 @Transactional public byte[] excel(String entity,Map<String,String> filters){var cols=columns(entity);var rows=rows(entity,filters);try(var book=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var sheet=book.createSheet("业务数据");var amount=book.createCellStyle();amount.setDataFormat(book.createDataFormat().getFormat("#,##0.00########"));var date=book.createCellStyle();date.setDataFormat(book.createDataFormat().getFormat("yyyy-mm-dd hh:mm:ss"));writeSheet(sheet,cols,rows,amount,date);if(Set.of("requests","orders","receipts","issues","stocktakes").contains(entity)){List<Map<String,Object>> details=new ArrayList<>();for(var h:rows)for(var d:lines(entity,((Number)h.get("id")).longValue())){var line=new LinkedHashMap<>(d);line.put("document_code",h.get("code"));line.put("project_name",h.get("project_name"));details.add(line);}var lineCols=new LinkedHashMap<String,String>();for(String p:new String[]{"document_code:单号","project_name:项目","material_name:材料","specification:规格","unit:单位","quantity:原始数量","unit_price:采购单价","amount:原始金额","received_quantity:累计验收","closed_quantity:关闭数量","remaining_quantity:待履行","returned_quantity:采购退货"}){var pair=p.split(":");lineCols.put(pair[0],pair[1]);}if(!entity.equals("orders"))for(String key:List.of("received_quantity","closed_quantity","remaining_quantity","returned_quantity"))lineCols.remove(key);
 if(entity.equals("requests"))lineCols.put("unit_price","预估单价");
 if(entity.equals("issues")){lineCols.remove("unit_price");if(!auth.can("cost:read"))lineCols.remove("amount");}
 if(entity.equals("stocktakes")){lineCols.remove("project_name");lineCols.remove("quantity");lineCols.remove("unit_price");lineCols.remove("amount");lineCols.put("snapshot_quantity","账面数量");lineCols.put("counted_quantity","实盘数量");lineCols.put("difference_quantity","差异数量");lineCols.put("reason","差异原因");if(auth.can("cost:read")||auth.can("stocktake:approve"))lineCols.put("adjustment_amount","生效调整金额");}
 writeSheet(book.createSheet("单据明细"),lineCols,details,amount,date);}var notes=book.createSheet("口径说明");String[] text={"仅当前用户权限、项目范围和筛选结果。金额以服务端计算为准；文本使用文本单元格，不作为公式执行。","对账为当前累计余额：验收-采购退货=净应付；实付-退款=净实付。不是指定期间的期初/期末账。","采购退货不恢复订单待履行量；补采须通过明确关联的新申请。计划不等于付款。","库存盘点独立计价，不自动计入项目成本。超过15位有效数字按精确文本输出，防止Excel损失精度。"};for(int i=0;i<text.length;i++)notes.createRow(i).createCell(0).setCellValue(text[i]);notes.setColumnWidth(0,110*256);book.write(out);auth.audit("EXPORT",entity,null,"按权限导出 "+rows.size()+" 行");return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
 private void writeSheet(Sheet sheet,LinkedHashMap<String,String> cols,List<Map<String,Object>> rows,CellStyle amount,CellStyle date){var header=sheet.createRow(0);int col=0;for(String label:cols.values()){header.createCell(col).setCellValue(label);sheet.setColumnWidth(col++,22*256);}int index=1;for(var r:rows){var row=sheet.createRow(index++);col=0;for(String key:cols.keySet()){Cell cell=row.createCell(col++);Object v=r.get(key);if(v==null)continue;if(numeric(key)){BigDecimal value=new BigDecimal(v.toString());if(value.stripTrailingZeros().precision()<=15){cell.setCellValue(value.doubleValue());cell.setCellStyle(amount);}else cell.setCellValue(value.toPlainString());}else if(v instanceof java.sql.Timestamp ts){cell.setCellValue(ts.toInstant().atZone(ZoneId.of("Asia/Shanghai")).toLocalDateTime());cell.setCellStyle(date);}else if(v instanceof java.sql.Date d){cell.setCellValue(d.toLocalDate());cell.setCellStyle(date);}else if(key.endsWith("_date")||key.equals("qualification_expiry")){try{cell.setCellValue(LocalDate.parse(v.toString()));cell.setCellStyle(date);}catch(Exception e){cell.setCellValue(v.toString());}}else cell.setCellValue(v.toString());}}sheet.createFreezePane(0,1);sheet.setAutoFilter(new org.apache.poi.ss.util.CellRangeAddress(0,Math.max(0,rows.size()),0,cols.size()-1));}
 private List<Map<String,Object>> lines(String entity,long id){String sql=switch(entity){case "requests"->"SELECT i.*,m.name material_name,m.specification,m.unit FROM request_items i JOIN materials m ON m.id=i.material_id WHERE i.request_id=? ORDER BY i.id";case "stocktakes"->"SELECT i.*,m.name material_name,m.specification,m.unit FROM stocktake_items i JOIN materials m ON m.id=i.material_id WHERE i.stocktake_id=? ORDER BY i.id";case "orders"->"SELECT i.*,i.quantity-i.received_quantity-i.closed_quantity remaining_quantity,COALESCE((SELECT SUM(t.quantity) FROM purchase_return_items t JOIN receipt_items r ON r.id=t.receipt_item_id WHERE r.order_item_id=i.id),0) returned_quantity,m.name material_name,m.specification,m.unit FROM order_items i JOIN materials m ON m.id=i.material_id WHERE i.order_id=? ORDER BY i.id";case "receipts"->"SELECT i.*,m.name material_name,m.specification,m.unit FROM receipt_items i JOIN materials m ON m.id=i.material_id WHERE i.receipt_id=? ORDER BY i.id";case "issues"->"SELECT -i.quantity quantity,i.amount,i.unit_cost,m.name material_name,m.specification,m.unit FROM stock_movements i JOIN materials m ON m.id=i.material_id WHERE i.issue_id=? AND i.kind='ISSUE' ORDER BY i.id";default->throw new IllegalArgumentException();};var rows=db.list(sql,id);if(entity.equals("issues")&&!auth.can("cost:read"))rows=rows.stream().map(r->DataPolicy.inventory(r,DataPolicy.flags(auth))).toList();return rows;}
 private String esc(Object value){return Objects.toString(value,"").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 private String display(Object v){if(v instanceof java.sql.Timestamp ts)return ts.toInstant().atZone(ZoneId.of("Asia/Shanghai")).toLocalDateTime().toString().replace('T',' ');return esc(v);}
 @Transactional public String print(String entity,long id,Map<String,String> filters){columns(entity);Fields.check(Set.of("orders","receipts","issues","supplier-statement").contains(entity),"此业务暂不支持打印");Map<String,String> f=new HashMap<>(filters);if(!entity.equals("supplier-statement"))f.put("id",String.valueOf(id));var rows=rows(entity,f);Fields.check(!rows.isEmpty(),"没有符合权限和筛选条件的单据");String title=Map.of("orders","采购订单","receipts","验收入库单","issues","项目领料单","supplier-statement","供应商累计对账单").get(entity);StringBuilder html=new StringBuilder("<!doctype html><html lang=zh-CN><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>"+title+"</title><style>@page{size:A4;margin:14mm}body{font:14px/1.6 system-ui;color:#111;margin:20px}h1{text-align:center;font-size:24px}h2{text-align:center;font-size:18px}table{border-collapse:collapse;width:100%;font-size:12px;table-layout:fixed;word-break:break-word}th,td{border:1px solid #777;padding:6px;text-align:left}thead{display:table-header-group}tr{break-inside:avoid}.sign{display:flex;justify-content:space-between;margin-top:35px}.doc{break-after:page}.doc:last-child{break-after:auto}@media screen{body{max-width:900px;margin:20px auto;padding:10px}}</style><body>");String company=esc(db.one("SELECT name FROM company WHERE id=1").get("name"));if(entity.equals("supplier-statement")){html.append("<h1>").append(company).append("</h1><h2>").append(title).append("</h2><p>对账编号：ST-").append(LocalDate.now()).append(" · 制表人：").append(esc(auth.user().get("name"))).append(" · 制表时间：").append(ZonedDateTime.now(ZoneId.of("Asia/Shanghai")).toLocalDateTime()).append("</p><p>当前累计值，非期间账。筛选：").append(esc(filters)).append("</p>");table(html,columns(entity),rows);for(String key:List.of("amount","paid_amount","outstanding_amount","refundable_amount"))html.append("<p>").append(esc(columns(entity).get(key))).append("合计：").append(rows.stream().map(r->dec(r.get(key))).reduce(BigDecimal.ZERO,BigDecimal::add)).append("</p>");}
 else for(var h:rows){html.append("<section class=doc><h1>").append(company).append("</h1><h2>").append(title).append("</h2><p>单号：").append(esc(h.get("code"))).append(" · 项目：").append(esc(h.get("project_name"))).append("</p><p>制单人：").append(esc(h.getOrDefault("buyer_name",h.get("operator_name")))).append(" · 制单时间：").append(display(h.get("created_at"))).append("</p><p>供应商 / 仓库：").append(esc(h.getOrDefault("supplier_name",h.get("warehouse_name")))).append(" · 凭证：").append(esc(h.get("reference"))).append("</p>");var cols=new LinkedHashMap<String,String>();for(String p:new String[]{"material_name:材料","specification:规格","unit:单位","quantity:原始数量","unit_price:采购单价","amount:原始金额"}){var pair=p.split(":");cols.put(pair[0],pair[1]);}if(entity.equals("orders")){cols.put("closed_quantity","关闭数量");cols.put("received_quantity","累计验收");cols.put("returned_quantity","采购退货");cols.put("remaining_quantity","待履行");}if(entity.equals("issues")){cols.remove("unit_price");if(!auth.can("cost:read"))cols.remove("amount");}table(html,cols,lines(entity,((Number)h.get("id")).longValue()));if(!entity.equals("issues")||auth.can("cost:read"))html.append("<p>原始金额合计：").append(esc(h.getOrDefault("total_amount",h.get("amount")))).append(" 元</p>");if(entity.equals("orders"))html.append("<p>关闭金额：").append(h.get("closed_amount")).append(" · 净订单额：").append(h.get("effective_amount")).append(" 元；退货不恢复待履行量。</p>");html.append("<p>备注：").append(esc(h.get("note"))).append("</p><div class=sign><span>制单签字：____________</span><span>复核签字：____________</span><span>接收签字：____________</span></div></section>");}
 if(entity.equals("supplier-statement"))html.append("<div class=sign><span>企业确认：____________</span><span>供应商确认：____________</span><span>日期：____________</span></div>");auth.audit("PRINT",entity,id==0?null:id,"按权限生成打印单");return html.append("</body></html>").toString();}
 private void table(StringBuilder out,LinkedHashMap<String,String> cols,List<Map<String,Object>> rows){out.append("<table><thead><tr>");for(String label:cols.values())out.append("<th>").append(esc(label)).append("</th>");out.append("</tr></thead><tbody>");for(var row:rows){out.append("<tr>");for(String key:cols.keySet())out.append("<td>").append(display(row.get(key))).append("</td>");out.append("</tr>");}out.append("</tbody></table>");}
}
